#!/usr/bin/env node
'use strict';
/*
 * str8ts — INDEPENDENT uniqueness solver (limit = 2, real backtracking search).
 *
 * WHY THIS EXISTS
 * ---------------
 * str8ts/index.html says, in three separate places:
 *   - HowTo schema: "Every puzzle has a unique solution!"
 *   - the in-game tutorial: "Every puzzle has a unique solution — you never
 *     need to guess!"
 *   - a source comment: "generated by Python CSP solver, all unique-solution"
 *
 * and the ENGINE'S WIN CHECK IS A SOLUTION-COMPARE:
 *     function checkWin(){
 *       ...
 *       var sol = data.sol[r + ',' + c];
 *       if (sol !== undefined && cell.val !== sol) return false;
 *       ...
 *     }
 * i.e. the game never re-derives the Str8ts RULE, it just compares the
 * player's grid against ONE stored grid.  If a level admitted a second
 * grid that satisfies every Str8ts rule, a player reasoning correctly to
 * that rival grid would be marked WRONG forever — the level would be
 * unwinnable by legitimate play.  That is the Pitfall #59 / #86 defect
 * class, and it is load-bearing here precisely because the page claims
 * uniqueness.
 *
 * This solver therefore COUNTS solutions with a real backtracking search
 * (limit = 2) under the FULL rule set, and never reads lv.sol for the
 * SEARCH — only to cross-check afterwards.
 *
 * THE RULES, read from the game (not from the level key names)
 * -----------------------------------------------------------
 * From the FAQ / HowTo schema / in-game tutorial in index.html:
 *   1. Fill every WHITE cell with a digit from 1..N (N = grid size).
 *   2. BLACK cells are walls: they split rows and columns into segments.
 *   3. Each contiguous segment of white cells in a row/column (a "straight")
 *      must contain a SET OF CONSECUTIVE NUMBERS. The order inside a
 *      straight is free ("The numbers in a straight can be in any order!").
 *   4. No number may repeat among the WHITE cells of any row or column.
 *   5. GIVEN cells are pre-filled and immutable.
 *
 * CALIBRATION (Pitfall #88) — a fresh counter is unfalsifiable until it is
 * calibrated against a dataset a DIFFERENT implementation already settled:
 *   (a) SENSITIVITY: pin every cell to the stored solution -> count == 1.
 *   (b) SENSITIVITY: strip the givens -> the count must go UP (never down).
 *   (c) NEGATIVE CONTROL: a deliberately ambiguous synthetic level must
 *       report >= 2.
 *
 * EXIT CODE: non-zero when any level is multi-solution / unsolvable /
 * timed-out, or when the stored solution is not a rule-valid answer, or
 * when any calibration fails.
 */
const fs = require('fs');
const path = require('path');

const HERE = __dirname;
const html = fs.readFileSync(path.join(HERE, 'index.html'), 'utf8');
const m = html.match(/var LEVELS = (\[[\s\S]*?\]);\n/);
if (!m) {
  console.error('FATAL: could not extract LEVELS from str8ts/index.html');
  process.exit(2);
}
const LEVELS = eval('(' + m[1] + ')');

/* ---------- rule helpers ---------- */

/** The white-cell segments of one line, as arrays of "r,c" keys. */
function segments(keys, n) {
  const segs = [];
  let cur = [];
  for (let i = 0; i < n; i++) {
    if (keys[i] === null) {              // black -> wall, closes the segment
      if (cur.length) segs.push(cur);
      cur = [];
    } else {
      cur.push(keys[i]);
    }
  }
  if (cur.length) segs.push(cur);
  return segs;
}

/** A set of values is a set of consecutive numbers. */
function isConsecutiveSet(vals) {
  if (vals.length <= 1) return true;
  const s = [...vals].sort((a, b) => a - b);
  for (let i = 1; i < s.length; i++) if (s[i] !== s[i - 1] + 1) return false;
  return true;
}

/**
 * Full rule validation of a complete assignment.
 * `grid` is a map "r,c" -> value for white cells only.
 * Returns null when valid, or a string describing the first violation.
 */
function validate(level, grid) {
  const n = level.n;
  const black = new Set(level.black.map(([r, c]) => r + ',' + c));
  const isBlack = (r, c) => black.has(r + ',' + c);

  // every white cell filled, 1..n
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (isBlack(r, c)) continue;
      const v = grid[r + ',' + c];
      if (v === undefined) return 'cell ' + r + ',' + c + ' not filled';
      if (!(v >= 1 && v <= n)) return 'cell ' + r + ',' + c + ' out of range: ' + v;
    }
  }
  // givens honoured
  for (const k in level.givens) {
    if (grid[k] !== level.givens[k]) return 'given ' + k + ' violated';
  }
  // straights + no repeats, per row and per column
  for (let r = 0; r < n; r++) {
    const rowKeys = [];
    for (let c = 0; c < n; c++) rowKeys.push(isBlack(r, c) ? null : r + ',' + c);
    for (const seg of segments(rowKeys, n)) {
      const vals = seg.map(k => grid[k]);
      if (!isConsecutiveSet(vals)) return 'row straight not consecutive at ' + seg.join(' ');
    }
    const allRow = rowKeys.map(k => grid[k]).filter(v => v !== undefined);
    if (new Set(allRow).size !== allRow.length) return 'row ' + r + ' has a repeated number';
  }
  for (let c = 0; c < n; c++) {
    const colKeys = [];
    for (let r = 0; r < n; r++) colKeys.push(isBlack(r, c) ? null : r + ',' + c);
    for (const seg of segments(colKeys, n)) {
      const vals = seg.map(k => grid[k]);
      if (!isConsecutiveSet(vals)) return 'col straight not consecutive at ' + seg.join(' ');
    }
    const allCol = colKeys.map(k => grid[k]).filter(v => v !== undefined);
    if (new Set(allCol).size !== allCol.length) return 'col ' + c + ' has a repeated number';
  }
  return null;
}

/**
 * Count solutions with limit 2 under the full rule set.
 * Returns { count, timedOut, solutions }.
 */
function countSolutions(level, limit, deadlineMs, forced) {
  const n = level.n;
  const black = new Set(level.black.map(([r, c]) => r + ',' + c));
  const white = [];
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) if (!black.has(r + ',' + c)) white.push(r + ',' + c);
  }
  const grid = Object.create(null);
  const solutions = [];
  let timedOut = false;

  /* SEED THE GIVENS INTO THE GRID BEFORE SEARCHING.
     This is not cosmetic: the row/column no-repeat check and the straight
     check both read `grid`. If the givens are not present up front, the
     search can hand a digit to a non-given cell first, and only later
     assign that same digit to its given cell — producing a grid with a
     duplicate that `validate()` then rejects. The stored solution was
     therefore never found, and the counter reported 0 solutions for
     EVERY level (a false "unsolvable" for the whole catalog). */
  for (const k in level.givens) grid[k] = level.givens[k];

  // precompute the segments (row + col) each cell belongs to
  const rowSegs = {}, colSegs = {};
  for (let r = 0; r < n; r++) {
    const keys = [];
    for (let c = 0; c < n; c++) keys.push(black.has(r + ',' + c) ? null : r + ',' + c);
    const segs = segments(keys, n);
    segs.forEach((seg) => seg.forEach(k => { (rowSegs[k] = rowSegs[k] || []).push(seg); }));
  }
  for (let c = 0; c < n; c++) {
    const keys = [];
    for (let r = 0; r < n; r++) keys.push(black.has(r + ',' + c) ? null : r + ',' + c);
    const segs = segments(keys, n);
    segs.forEach((seg) => seg.forEach(k => { (colSegs[k] = colSegs[k] || []).push(seg); }));
  }

  // candidate values for a cell, given the current partial grid
  function candidates(key) {
    /* NOTE the explicit `!== undefined` test. `forced && forced[key]`
       evaluates to `null` when `forced` is null, and `null !== undefined`
       is TRUE — so a naive truthiness check would return `[null]` for
       every cell and the search would never build a valid grid (it
       reported 0 solutions for all 27 levels). */
    const forcedV = (forced && forced[key] !== undefined) ? forced[key] : undefined;
    if (forcedV !== undefined) return [forcedV];
    const given = level.givens[key];
    if (given !== undefined) return [given];   // a given is immutable
    const out = [];
    for (let v = 1; v <= n; v++) {
      // row no-repeat (among WHITE cells of that row)
      let ok = true;
      for (const k of white) {
        if (k === key) continue;
        if (grid[k] === v && sameRow(k, key)) { ok = false; break; }
      }
      if (!ok) continue;
      // column no-repeat
      for (const k of white) {
        if (k === key) continue;
        if (grid[k] === v && sameCol(k, key)) { ok = false; break; }
      }
      if (ok) out.push(v);
    }
    return out;
  }
  const rc = {};
  for (const k of white) { const p = k.split(','); rc[k] = [+p[0], +p[1]]; }
  function sameRow(a, b) { return rc[a][0] === rc[b][0]; }
  function sameCol(a, b) { return rc[a][1] === rc[b][1]; }

  // check that a straight can still be completed
  function segOk(seg) {
    // Collect the ASSIGNED values only. A partially filled straight may
    // legitimately have a GAP (e.g. {1,?,3} in a length-3 straight) — only
    // the FULL segment must be a consecutive set. So the test is:
    //   (a) the assigned values are distinct, and
    //   (b) there EXISTS a window of length seg.length inside 1..n that
    //       contains every assigned value.
    const vals = [];
    for (const k of seg) { const v = grid[k]; if (v !== undefined) vals.push(v); }
    if (vals.length === 0) return true;
    if (new Set(vals).size !== vals.length) return false;   // a straight cannot repeat a digit
    const s = [...vals].sort((a, b) => a - b);
    const lo = Math.max(1, s[s.length - 1] - seg.length + 1);
    const hi = Math.min(n, s[0] + seg.length - 1);
    for (let start = lo; start <= hi; start++) {
      let fits = true;
      for (const v of s) if (v < start || v >= start + seg.length) { fits = false; break; }
      if (fits) return true;
    }
    return false;
  }

  function recurse(remaining) {
    if (timedOut) return;
    if (solutions.length >= limit) return;
    if (Date.now() > deadlineMs) { timedOut = true; return; }
    if (remaining.length === 0) {
      // full assignment: re-validate from scratch
      if (validate(level, grid) === null) solutions.push(Object.assign({}, grid));
      return;
    }
    // MRV: pick the unfilled cell with the fewest candidates
    let bestIdx = -1, bestCands = null;
    for (let i = 0; i < remaining.length; i++) {
      const cands = candidates(remaining[i]);
      if (cands.length === 0) return;          // dead end
      if (bestCands === null || cands.length < bestCands.length) {
        bestIdx = i; bestCands = cands;
        if (cands.length === 1) break;         // cannot do better
      }
    }
    const key = remaining[bestIdx];
    // the rest of the cells, with the chosen one removed
    const rest = remaining.slice(0, bestIdx).concat(remaining.slice(bestIdx + 1));
    for (const v of bestCands) {
      grid[key] = v;
      // straights containing this cell must still be satisfiable
      let ok = true;
      for (const seg of (rowSegs[key] || [])) if (!segOk(seg)) { ok = false; break; }
      if (ok) for (const seg of (colSegs[key] || [])) if (!segOk(seg)) { ok = false; break; }
      if (ok) recurse(rest);
      delete grid[key];
      if (solutions.length >= limit || timedOut) return;
    }
  }

  recurse(white.filter(k => level.givens[k] === undefined));
  return { count: solutions.length, timedOut, solutions };
}

/* ---------- calibration ---------- */
const cal = {};

// (a) pin every cell to the stored solution -> exactly 1
{
  let allOk = true, detail = '';
  for (let i = 0; i < LEVELS.length; i++) {
    const lv = LEVELS[i];
    const res = countSolutions(lv, 2, Date.now() + 4000, lv.sol);
    if (res.count !== 1) { allOk = false; detail += 'L' + (i + 1) + '=' + res.count + ' '; }
  }
  cal.pinned = allOk;
  if (!allOk) console.error('  calib(pinned) FAILED: ' + detail);
  else console.log('  calib(pinned): every level counts exactly 1 when pinned to its solution');
}

// (c) negative control: a deliberately ambiguous synthetic level must be >= 2
{
  // A 2x2 grid with NO givens and ONE black wall at (0,0).
  // The two white cells of row 1 and the two white cells of column 1 must
  // each be a consecutive set, and no digit may repeat in a row or column.
  // {1,2} in both directions satisfies every rule, so the level has
  // (at least) two solutions. If the counter reports < 2 here, the gate
  // cannot detect a multi-solution level and is therefore vacuous.
  const syn = { n: 2, black: [[0, 0]], givens: {}, sol: { '0,1': 1, '1,0': 1, '1,1': 2 } };
  const res = countSolutions(syn, 2, Date.now() + 4000, null);
  cal.negative = res.count >= 2;
  console.log('  calib(negative): synthetic ambiguous level -> count=' + res.count + (res.count >= 2 ? ' (>=2 OK)' : ' (EXPECTED >=2 — GATE IS VACUOUS)'));
}

/* ---------- main run ---------- */
const multi = [], unsolvable = [], timeouts = [], badStored = [], badGivens = [];
let proven = 0;

for (let i = 0; i < LEVELS.length; i++) {
  const lv = LEVELS[i];
  const label = 'L' + (i + 1) + ' ' + lv.tier + ' ' + lv.n + 'x' + lv.n;
  // the stored solution must be a rule-valid answer
  const vErr = validate(lv, lv.sol);
  if (vErr) badStored.push(label + ': ' + vErr);
  for (const k in lv.givens) {
    if (lv.sol[k] !== lv.givens[k]) badGivens.push(label + ': given ' + k + ' != sol');
  }
  // free search (no forcing) with a generous budget
  const res = countSolutions(lv, 2, Date.now() + 20000, null);
  if (res.timedOut) { timeouts.push(label); console.log('  ' + label + ': TIMEOUT (unproven)'); continue; }
  if (res.count === 0) { unsolvable.push(label); console.log('  ' + label + ': UNSOLVABLE'); continue; }
  if (res.count >= 2) {
    multi.push(label);
    console.log('  ' + label + ': MULTI-SOLUTION (' + res.count + ') — rival grid:');
    const rival = res.solutions.find(s => JSON.stringify(s) !== JSON.stringify(lv.sol));
    if (rival) {
      const diff = Object.keys(rival).filter(k => rival[k] !== lv.sol[k]);
      console.log('      rival differs from stored at ' + diff.join(' ') + ' e.g. ' +
        diff.slice(0, 3).map(k => k + ': stored=' + lv.sol[k] + ' rival=' + rival[k]).join(', '));
    }
    continue;
  }
  proven++;
  console.log('  ' + label + ': UNIQUE');
}

/* ---------- sensitivity: stripping the givens must not reduce the count ---------- */
let sensOk = true, sensDetail = '';
for (let i = 0; i < Math.min(5, LEVELS.length); i++) {
  const lv = LEVELS[i];
  const stripped = { n: lv.n, black: lv.black, givens: {}, sol: lv.sol };
  const res = countSolutions(stripped, 2, Date.now() + 20000, null);
  if (res.timedOut) { sensDetail += 'L' + (i + 1) + ':timeout '; continue; }
  if (res.count < 1) { sensOk = false; sensDetail += 'L' + (i + 1) + '=0 '; }
  else if (res.count === 1 && Object.keys(lv.givens).length > 0) {
    // stripping the givens should normally open the space; a count of 1 means
    // the givens are redundant, which is worth reporting but not a failure.
    sensDetail += 'L' + (i + 1) + ':still-1 ';
  }
}
if (sensDetail) console.log('  calib(sensitivity, hints stripped): ' + sensDetail.trim());

const out = {
  levels: LEVELS.length,
  calibrationPassed: cal.pinned && cal.negative,
  calibration: cal,
  provenUnique: proven,
  multiSolution: multi,
  unsolvable,
  timeouts,
  badStoredSolution: badStored,
  badGivens,
  verdict: (multi.length || unsolvable.length || timeouts.length || badStored.length || badGivens.length || !cal.pinned || !cal.negative) ? 'FAIL' : 'PASS',
};
console.log(JSON.stringify(out));
process.exit(out.verdict === 'PASS' ? 0 : 1);
